command:
curl -sS -m 60 'https://openrouter.ai/api/v1/models?sort=top-weekly' -o /tmp/models.json
npm install --no-save --no-package-lock playwright@1.56.1 pngjs >/dev/null 2>&1
python3 -m http.server 8765 --bind 127.0.0.1 >/dev/null 2>&1 &
sleep 1
cat > /tmp/probe3.cjs <<'EOF'
const fs = require('fs');
const { chromium } = require(process.cwd() + '/node_modules/playwright');
const { PNG } = require(process.cwd() + '/node_modules/pngjs');
const real = fs.readFileSync('/tmp/models.json', 'utf8');
(async () => {
  // 1. Which logo files are single-colour black (invisible on AMOLED unless listed as MONO)?
  const html = fs.readFileSync('index.html', 'utf8');
  const mono = new Set(((/const MONO_LOGOS = new Set\(\[([^\]]*)\]/.exec(html) || [])[1] || '').split(',').map((s) => s.replace(/['\s]/g, '')).filter(Boolean));
  const dir = 'icons/companies';
  const rows = fs.readdirSync(dir).filter((f) => f.endsWith('.svg')).map((f) => {
    const svg = fs.readFileSync(dir + '/' + f, 'utf8');
    const colours = new Set((svg.match(/#[0-9a-fA-F]{3,8}\b|currentColor|rgb\([^)]*\)/g) || []).map((c) => c.toLowerCase()));
    const dark = [...colours].every((c) => c === 'currentcolor' || /^#(000|000000|111|111111|1a1a1a|222|222222|333|333333)$/.test(c));
    const noColour = colours.size === 0;
    return { file: f.replace('.svg', ''), colours: [...colours].slice(0, 4).join(' '), blackish: dark || noColour, listedMono: mono.has(f.replace('.svg', '')) };
  });
  console.log('MONO listed:', [...mono].join(','));
  console.log('blackish but NOT listed as mono:', rows.filter((r) => r.blackish && !r.listedMono).map((r) => r.file + '[' + (r.colours || 'no colour') + ']').join(' | ') || 'none');
  console.log('listed as mono but coloured:', rows.filter((r) => !r.blackish && r.listedMono).map((r) => r.file + '[' + r.colours + ']').join(' | ') || 'none');

  // 2. The real list in the real app.
  const browser = await chromium.launch({ executablePath: process.env.CHROMIUM, args: ['--no-sandbox'] });
  for (const mode of [{ theme: 'dark', claude: true }, { theme: 'dark', claude: false }]) {
    const context = await browser.newContext({ viewport: { width: 1000, height: 1000 }, colorScheme: mode.theme });
    const page = await context.newPage();
    await page.route('https://openrouter.ai/api/v1/models**', (r) => r.fulfill({ status: 200, contentType: 'application/json', body: real }));
    await page.route('https://openrouter.ai/api/v1/key**', (r) => r.fulfill({ status: 200, contentType: 'application/json', body: '{"data":{"limit":null,"usage":1}}' }));
    await page.route('https://openrouter.ai/api/v1/credits**', (r) => r.fulfill({ status: 401, contentType: 'application/json', body: '{}' }));
    await page.route('https://api.anthropic.com/**', (r) => r.fulfill({ status: 200, contentType: 'application/json', body: '{"data":[]}' }));
    await page.addInitScript((m) => { try { localStorage.setItem('inhouseGeminiStandaloneV1::openrouterSettings', JSON.stringify(Object.assign({ apiKey: 'sk-or-test', updatedAt: new Date().toISOString() }, m.claude ? { anthropicKey: 'sk-ant-test' } : {}))); localStorage.setItem('inhouselearn.theme', m.theme); } catch (_) {} }, mode);
    await page.goto('http://127.0.0.1:8765/index.html', { waitUntil: 'load' });
    await page.waitForFunction(() => window.InhousePi && typeof runAssistantTurn === 'function' && modelCatalog.entries.length > 20, null, { timeout: 30000 });
    await page.waitForTimeout(800);
    await page.click('#model-menu-btn');
    await page.waitForSelector('.model-card');
    const list = await page.evaluate(() => Array.from(document.querySelectorAll('.model-card')).map((c) => {
      const img = c.querySelector('.model-card-icon img');
      const box = (img || c.querySelector('.model-card-icon svg') || c).getBoundingClientRect();
      return { id: c.dataset.modelId, gauge: (c.querySelector('.model-gauge-num') || {}).textContent || '', icon: img ? img.getAttribute('src').replace('icons/companies/', '') : 'LETTER', filter: img ? getComputedStyle(img).filter : '', w: Math.round(box.width), group: '' };
    }));
    const shown = list.length;
    console.log('\n=== ' + mode.theme + ' · claude key ' + mode.claude + ' · rows ' + shown + ' · without number ' + list.filter((r) => !r.gauge).length + ' · letter icon ' + list.filter((r) => r.icon === 'LETTER').length);
    list.slice(0, 26).forEach((r) => console.log((r.gauge || '—').toString().padStart(5), r.id.padEnd(44), r.icon.padEnd(16), r.filter && r.filter !== 'none' ? 'filter:' + r.filter.slice(0, 24) : ''));
    await context.close();
  }
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
EOF
